const gap = Math.round(0.12 * fps);
const cx = width / 2;
const cy = height / 2;
const R = Math.min(width, height) * 0.25;
const bW = 54;
const bH = 14;
const els = [];

els.push(React.createElement('div', { key: 'vd', style: {
  position: 'absolute', left: cx - R - 18, top: cy - R - 18,
  width: (R + 18) * 2, height: (R + 18) * 2, borderRadius: '50%',
  border: '3px solid ' + D.text_dim,
  background: 'radial-gradient(circle at 45% 40%, ' + D.surface + ', ' + D.bg + ')',
  boxShadow: 'inset 0 0 50px rgba(0,0,0,0.5), 0 0 40px rgba(0,0,0,0.5)',
} }));

els.push(React.createElement('div', { key: 'ir', style: {
  position: 'absolute', left: cx - R * 0.45, top: cy - R * 0.45,
  width: R * 0.9, height: R * 0.9, borderRadius: '50%',
  border: '2px solid ' + D.text_dim,
} }));

[0, 90].forEach(function(r, j) {
  els.push(React.createElement('div', { key: 'h' + j, style: {
    position: 'absolute', left: cx - 3, top: cy - R * 0.3,
    width: 6, height: R * 0.6, background: D.text_dim, borderRadius: 3,
    transformOrigin: '3px ' + (R * 0.3) + 'px', transform: 'rotate(' + r + 'deg)',
  } }));
});

els.push(React.createElement('div', { key: 'hub', style: {
  position: 'absolute', left: cx - 12, top: cy - 12,
  width: 24, height: 24, borderRadius: '50%',
  background: D.text_dim, border: '2px solid ' + D.surface,
} }));

co.forEach(function(name, i) {
  var a = (i / 8) * Math.PI * 2 - Math.PI / 2;
  var sF = i * gap;
  var sp = spring({ frame: frame - sF, fps: fps, config: { damping: 10, stiffness: 220 } });

  var lockedR = R + 14 + bW * 0.5;
  var freeR = R - bW * 0.55;
  var br = interpolate(sp, [0, 1], [lockedR, freeR]);
  var bx = cx + Math.cos(a) * br;
  var by = cy + Math.sin(a) * br;
  var deg = a * 180 / Math.PI;

  els.push(React.createElement('div', { key: 'b' + i, style: {
    position: 'absolute', left: bx - bW / 2, top: by - bH / 2,
    width: bW, height: bH, borderRadius: 3,
    background: 'linear-gradient(to bottom, ' + D.text + ', ' + D.text_dim + ')',
    transform: 'rotate(' + deg + 'deg)',
    boxShadow: '0 2px 4px rgba(0,0,0,0.5)',
  } }));

  var headR = br + bW * 0.35;
  var hx = cx + Math.cos(a) * headR;
  var hy = cy + Math.sin(a) * headR;
  els.push(React.createElement('div', { key: 'bh' + i, style: {
    position: 'absolute', left: hx - 10, top: hy - 10,
    width: 20, height: 20, borderRadius: '50%',
    background: D.text_dim,
    boxShadow: '0 1px 3px rgba(0,0,0,0.4)',
  } }));

  var fS = sF + Math.round(gap * 0.7);
  var fE = Math.max(fS + 1, fS + 10);
  var fOp = interpolate(frame, [fS, fE], [0.9, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  var fx = cx + Math.cos(a) * R;
  var fy = cy + Math.sin(a) * R;
  els.push(React.createElement('div', { key: 'fl' + i, style: {
    position: 'absolute', left: fx - 20, top: fy - 20,
    width: 40, height: 40, borderRadius: '50%',
    background: D.amber, opacity: fOp, filter: 'blur(10px)',
  } }));

  var lS = sF + 3;
  var lPeak = Math.max(lS + 1, lS + 6);
  var lFade = Math.max(lPeak + 1, lPeak + 18);
  var lOp = interpolate(frame, [lS, lPeak, lFade], [0, 1, 0.3], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });
  var glow = interpolate(frame, [lS, lPeak, lFade], [0, 18, 3], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp'
  });
  var lR = R + bW + 72;
  var lx = cx + Math.cos(a) * lR;
  var ly = cy + Math.sin(a) * lR;

  els.push(React.createElement('div', { key: 'n' + i, style: {
    position: 'absolute', left: lx, top: ly,
    transform: 'translate(-50%, -50%)',
    fontFamily: D.font_display, fontSize: 22, fontWeight: 700,
    color: D.cyan, opacity: lOp,
    textShadow: '0 0 ' + glow + 'px ' + D.cyan,
    whiteSpace: 'nowrap', letterSpacing: 1.5,
  } }, name));
});

return React.createElement('div', { style: { position: 'absolute', inset: 0, background: D.bg } }, ...els);
